def eval_regex_automaton(x):
    # State representation:
    # A state is a tuple: (a_parity, last_char, is_dead)
    # a_parity: 0 for even, 1 for odd
    # last_char: 'none', 'a', 'b', 'c'
    # is_dead: False normally, True if 'bc' was ever encountered

    # Initial state: (0, 'none', False)
    a_parity = 0
    last_char = 'none'
    is_dead = False

    for char in x:
        if is_dead:
            return False

        if char == 'a':
            a_parity = 1 - a_parity
            last_char = 'a'
        elif char == 'b':
            last_char = 'b'
        elif char == 'c':
            if last_char == 'b':
                is_dead = True
                return False
            last_char = 'c'
        else:
            # Invalid character outside {a, b, c}
            return False

    if is_dead:
        return False

    return a_parity == 0

